import Vue, { PropType } from 'vue';
import { IOperatorTheme } from '@game-studio/operator-theme';
import { IBroadcastMessage } from '../../types';
import { OPTIONS } from '../../options';

const DELAY: number = 20000; // 20 seconds
const DISPLAY_DURATION: number = 4000; // 4 seconds
const COOLDOWN_TIME: number = 180000; // 3 minutes

type TopPrizeData = {
    isVisible: boolean;
    isOnCooldown: boolean;
    imageClass: string;
    message: string;
}

export default Vue.component('top-prize', {
    name: 'TopPrize',
    props: {
        username: { type: String, required: false },
        onTopPrizeMessage: { type: Function, required: true },
        strings: { type: Object, required: true },
        formatCurrency: { type: Function, required: true },
        isPortrait: { type: Boolean, required: true },
        isDesktop: { type: Boolean, required: true },
        theme: { type: Object as PropType<IOperatorTheme>, required: false, default: () => OPTIONS.theme }
    },
    data(): TopPrizeData {
        return {
            isVisible: false,
            isOnCooldown: false,
            imageClass: '',
            message: '',
        };
    },
    mounted(): void {
        this.onTopPrizeMessage(this.onMessage, this);
    },
    methods: {
        onMessage(data: IBroadcastMessage): void {
            if (data.username === this.username ||
                data.isPromo === true ||
                this.isOnCooldown) {
                return;
            }

            this.isOnCooldown = true;
            this.imageClass = data.game.toLowerCase();
            this.message = this.strings.message
                .replace(/{{username}}/gi, data.username)
                .replace(/{{prize}}/gi, this.formatCurrency(data.prize))
                .replace(/{{gamename}}/gi, data.game);

            window.setTimeout(() => {
                if (this.isPortrait) {
                    return;
                }

                this.isVisible = true;
                window.setTimeout(() => this.isVisible = false, DISPLAY_DURATION);
                window.setTimeout(() => this.isOnCooldown = false, COOLDOWN_TIME);
            }, DELAY);
        }
    }
});